import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { Request, Response } from 'express';
import pdfParse from 'pdf-parse';
import multer from 'multer';

export const upload = multer({ 
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (file.mimetype === 'application/pdf') {
      cb(null, true);
    } else {
      cb(new Error('Only PDF files are allowed'));
    }
  }
});

export async function handleResumeUpload(req: Request, res: Response): Promise<void> {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file provided' });
      return;
    }

    const parsedPdf = await pdfParse(req.file.buffer);
    const cleanText = parsedPdf.text.replace(/\s+/g, ' ').trim();

    res.status(200).json({
      success: true,
      fileName: req.file.originalname,
      pageCount: parsedPdf.numpages,
      extractedText: cleanText,
    });
  } catch (error: any) {
    res.status(500).json({ error: 'Failed to parse PDF file', details: error.message });
  }
}

export interface KeywordAnalysisResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
}

export function calculateResumeMatch(resumeText: string, jobKeywords: string[]): KeywordAnalysisResult {
  const normalizedResume = resumeText.toLowerCase();
  const matchedKeywords: string[] = [];
  const missingKeywords: string[] = [];

  jobKeywords.forEach((keyword) => {
    const regex = new RegExp(`\\b${keyword.toLowerCase()}(\\b|s|es)?`, 'i');
    if (regex.test(normalizedResume)) {
      matchedKeywords.push(keyword);
    } else {
      missingKeywords.push(keyword);
    }
  });

  const total = jobKeywords.length;
  const matchScore = total > 0 ? Math.round((matchedKeywords.length / total) * 100) : 0;

  return {
    matchScore,
    matchedKeywords,
    missingKeywords,
  };
}
